package br.com.admeclesial.infrastructure.persistence.financeiro; import br.com.admeclesial.domain.financeiro.ObrigacaoRepasse; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface ObrigacaoRepasseRepository extends JpaRepository<ObrigacaoRepasse,Long>{ Optional<ObrigacaoRepasse> findByUuid(UUID uuid); List<ObrigacaoRepasse> findAllByOrderByCompetenciaDesc(); }